      facturacion_familias_titulo: 'How long Families have to pay',
      facturacion_familias_explicacion: 'This term sets each invoice’s due date, and that date is what decides whether a Family shows as overdue. Left empty, no general term was agreed and the date is typed in by hand when balances are generated. A different term can be agreed with an individual Family on their record, and that one prevails.',
