      cobranza_aviso_titulo: 'The notice from the other program',
      cobranza_aviso_explicacion: 'With follow-up off, the only thing that comes in from that other program is whether a Family has to be placed under some restriction for non-payment. {{producto}} shows it and decides nothing: a person decides what to do. No amount comes in.',
      cobranza_aviso_direccion: 'Address that program sends the notice to',
