      cobranza_aviso_secreto: 'Secret that program signs its notices with',
      facturacion_aviso_titulo: 'The notice from the invoicing program',
      facturacion_aviso_explicacion: 'If the Provider’s invoicing program can send notices on its own, this is where that is set up: for each invoice it reports which document it issued, with what number and for how much, and {{producto}} records it with no one entering anything. It is the same as doing it by hand or with the file, and it works with any program that can send a signed notice. An invoice that already has a document recorded is not changed.',
