      facturacion_aviso_secreto: 'Secret the invoicing program signs its notices with',
      tab_notificaciones: 'Notifications',
      consentimiento_pagador_titulo: 'What the payer signs',
      consentimiento_pagador_explicacion: 'The Payer signs that they take on the obligation to pay for the service. That document is between this Provider and whoever pays, so the text belongs to the Provider: here it can be written, replaced with your own or left as the template.',
      consentimiento_pagador_es_modelo: 'The template that comes with {{producto}} is currently in force. It is a suggestion and nothing more: it is not legal advice, and adopting it, changing it or replacing it is this Provider decision.',
      consentimiento_pagador_es_propio: 'The text entered by this Provider is currently in force.',
      consentimiento_pagador_cuerpo: 'Consent text',
      consentimiento_pagador_marcadores: 'These placeholders can be used, and the system replaces them when drawing up the document:',
      consentimiento_pagador_marcador_apoderado: 'The signatory placeholder behaves differently: when the payer is a person, there is nobody signing on their behalf and the whole line holding that placeholder is taken out of the document. Best to leave it alone on its own line.',
