      seguridad_mfa_titulo: 'Two-step verification (MFA)',
      seguridad_mfa_explicacion: 'Requires a 6-digit code in addition to the password for Superadmin and Admin_plataforma accounts. Starts off — turn it on whenever you want that extra layer of security.',
      seguridad_mfa_activo: 'On — Superadmin and Admin_plataforma need the code on every login',
