      seguridad_mfa_confirmar_boton: 'I understand the risk, turn on',
      ausencias_titulo: 'When an absence becomes urgent',
      ausencias_explicacion: 'An absence reported with room to spare reaches the Coordinator as a task to handle when possible, and is said only once. An absence that leaves a shift starting shortly reaches them as an alarm, and repeats until the shift has someone. This is where the line is drawn.',
      ausencias_horas_con_tiempo: 'Hours of notice to count it as reported in time',
