      pago_asistentes_titulo: 'Pay for those on a fixed amount',
      pago_asistentes_explicacion: 'Those paid by the hour or by the shift are paid for what they worked. This applies only to those on a fixed weekly or monthly amount, and only when they joined or left partway through the period.',
      pago_asistentes_prorratear: 'Pay only for the days worked',
      frecuencia_pago_titulo: 'How often Assistants are paid',
      frecuencia_pago_explicacion: 'What the work is measured by for each person — by the hour, by the shift, by the week or by the month — is chosen on their record. Here you choose something else: how often they are paid. They are independent: someone can be paid by the hour and collect monthly. This is what applies across the Provider, and it can be arranged differently with each person on their record.',
